referenceSolutions.javascript:
export function solve(left, right) {
  function same(a, b) {
    if (a.tag !== b.tag || a.children.length !== b.children.length) return false;
    const keys = Object.keys(a.attributes);
    if (
      keys.length !== Object.keys(b.attributes).length ||
      keys.some((k) => !Object.hasOwn(b.attributes, k) || a.attributes[k] !== b.attributes[k])
    )
      return false;
    return a.children.every((child, i) => same(child, b.children[i]));
  }
  return same(left, right);
}

