type Value = any;
export function solve(left: Value, right: Value): Value {
  function same(a: Value, b: Value): Value {
    if (a.tag !== b.tag || a.children.length !== b.children.length) return false;
    const keys = Object.keys(a.attributes);
    if (
      keys.length !== Object.keys(b.attributes).length ||
      keys.some(
        (k: Value) => !Object.hasOwn(b.attributes, k) || a.attributes[k] !== b.attributes[k],
      )
    )
      return false;
    return a.children.every((child: Value, i: Value) => same(child, b.children[i]));
  }
  return same(left, right);
}
